    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor list
    if is_matrix:
        neighbors = []
        for i in range(n):
            row = adj[i]
            nbrs = [j for j in range(n) if row[j] == 1]
            neighbors.append(nbrs)
    else:
        neighbors = []
        for i in range(n):
            nbrs = adj[i]
            if isinstance(nbrs, int):
                nbrs = [nbrs]
            elif not isinstance(nbrs, list):
                nbrs = list(nbrs)
            neighbors.append([int(x) for x in nbrs])

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: compute number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Initial upper bound: Welsh-Powell (degree descending)
    order_wp = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    color_wp = greedy_color(order_wp)
    k = num_colors(color_wp)
    best_coloring = color_wp[:]
    best_k = k

    # Lower bound: maximum clique size via greedy heuristic
    def greedy_clique():
        clique = []
        remaining = set(range(n))
        while remaining:
            v = max(remaining, key=lambda x: len([y for y in neighbors[x] if y in remaining]))
            clique.append(v)
            remaining = {y for y in remaining if y in neighbors[v]}
        return len(clique)
    lb = max(1, greedy_clique())

    # If already optimal, return
    if best_k == lb:
        return best_coloring

    # DSATUR heuristic
    def dsatur():
        color = [-1] * n
        saturation = [0] * n  # number of distinct colors in neighborhood
        colored = [False] * n
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
