            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                best_v = candidates[0]
                for v in candidates:
                    deg = sum(1 for u in neighbors[v] if not colored[u])
                    if deg > max_deg:
                        max_deg = deg
                        best_v = v
