                                    color[node] = target_color
                                elif color[node] == target_color:
                                    color[node] = c
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if improved:
                # Recompute max_color
                max_color = max(color) if color else -1
        return color

    # Also try RLF for comparison
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = uncolored - {v} - neighbors[v]
            W = (uncolored - {v}) & neighbors[v]
            while U:
                # Select u in U with max |N(u) ∩ W|
                u = max(U, key=lambda x: len([y for y in neighbors[x] if y in W]))
                S.add(u)
                U.remove(u)
                # Move neighbors of u in U to W
                nbrs_in_U = set()
                for y in neighbors[u]:
                    if y in U:
                        nbrs_in_U.add(y)
                U -= nbrs_in_U
                W |= nbrs_in_U
            # Assign color c to all in S
            for vertex in S:
                color[vertex] = c
            uncolored -= S
            c += 1
        return color

    col1 = dsatur_with_kempe()
    col2 = rlf()
    # Choose the one with fewer colors
    k1 = max(col1) + 1 if col1 else 0
    k2 = max(col2) + 1 if col2 else 0
    if k1 <= k2:
        return col1
    else:
        return col2
